create table public.service_affiliation_catalog(
 id bigint generated by default as identity primary key,country_id bigint references public.countries(id),facility_id uuid references public.facilities(id) on delete cascade,
 organization_type text not null check(organization_type in ('military','police','civilian')),entry_type text not null check(entry_type in ('rank','unit','function')),
 name text not null,active boolean not null default true,created_at timestamptz not null default now()
);
create unique index service_affiliation_catalog_unique on public.service_affiliation_catalog(country_id,facility_id,organization_type,entry_type,name) nulls not distinct;
alter table public.service_affiliation_catalog enable row level security;
create policy affiliation_catalog_read on public.service_affiliation_catalog for select to authenticated using(private.is_aal2());
create policy affiliation_catalog_write on public.service_affiliation_catalog for all to authenticated using(private.is_aal2() and (private.is_platform_root() or (facility_id is not null and private.is_facility_admin(facility_id)))) with check(private.is_aal2() and (private.is_platform_root() or (facility_id is not null and private.is_facility_admin(facility_id))));
grant select,insert,update,delete on public.service_affiliation_catalog to authenticated;

